class Solution {
  public boolean isValid(String s) {
    Deque<Character> stack = new ArrayDeque<>();
    for (char value : s.toCharArray()) {
      if (value == '(') stack.push(')');
      else if (value == '[') stack.push(']');
      else if (value == '{') stack.push('}');
      else if (stack.isEmpty() || stack.pop() != value) return false;
    }
    return stack.isEmpty();
  }
}

